use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_data = Vec::new();
    for row in input.as_array() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        sorted_data.push((key, value));
    }
    sorted_data.sort_unstable_by(|a, b| {
        if a.0 == b.0 {
            a.1.cmp(&b.1)
        } else {
            a.0.cmp(&b.0)
        }
    });
    sorted_data.into_iter().map(|(key, value)| serde_json::Value::Number(value)).collect()
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[2,9],[1,4],[2,3]],\"expected\":[[1,4],[2,3],[2,9]]}");
    let result = solve(input);
    println!("{}", serde_json::to_string(result));
}
